"use client";

import React, { useState, useMemo } from "react";
import Link from "next/link";
import { ArrowRight, BookOpen, Search, CheckCircle2 } from "lucide-react";
import { ConstitutionChapter } from "@/types";

interface ChapterGridProps {
  chapters: ConstitutionChapter[];
}

const CATEGORIES = [
  "All",
  "Foundations",
  "Rights and Freedoms",
  "Governance",
  "Accountability",
  "State Organs",
] as const;

export default function ChapterGrid({ chapters }: ChapterGridProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>("All");
  const [searchQuery, setSearchQuery] = useState<string>("");

  const filteredChapters = useMemo(() => {
    return chapters.filter((ch) => {
      const matchesCategory =
        selectedCategory === "All" || ch.category === selectedCategory;
      const q = searchQuery.toLowerCase().trim();
      const matchesSearch =
        q === "" ||
        ch.title.toLowerCase().includes(q) ||
        (ch.swahiliTitle && ch.swahiliTitle.toLowerCase().includes(q)) ||
        ch.summary.toLowerCase().includes(q) ||
        ch.keyProvisions.some((p) => p.toLowerCase().includes(q)) ||
        `chapter ${ch.number}`.includes(q);

      return matchesCategory && matchesSearch;
    });
  }, [chapters, selectedCategory, searchQuery]);

  return (
    <section className="py-24 bg-katiba-gray-50 border-t border-katiba-gray-200" id="chapters">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-katiba-green-light border border-katiba-green/20 mb-3">
              <span className="w-2 h-2 rounded-full bg-katiba-green" />
              <span className="text-xs font-black uppercase tracking-widest text-katiba-green">
                Legal Repository
              </span>
            </div>
            <h2 className="text-3xl sm:text-5xl font-black text-katiba-black tracking-tight">
              Constitutional Chapters
            </h2>
            <p className="text-base text-katiba-gray-600 mt-2 max-w-xl font-normal">
              Structured summaries and comprehensive article directories for all 18 chapters of the Constitution of Kenya (2010).
            </p>
          </div>

          {/* Search Box */}
          <div className="relative w-full md:w-80">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-katiba-gray-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search chapters or articles..."
              className="w-full pl-10 pr-4 py-2.5 text-sm rounded-xl border border-katiba-gray-300 bg-white text-katiba-black placeholder-katiba-gray-400 focus:outline-none focus:ring-2 focus:ring-katiba-green focus:border-transparent transition"
            />
          </div>
        </div>

        {/* Category Filters */}
        <div className="flex flex-wrap items-center gap-2 pb-8 mb-8 border-b border-katiba-gray-200">
          {CATEGORIES.map((cat) => {
            const isActive = selectedCategory === cat;
            return (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition uppercase tracking-wider ${
                  isActive
                    ? "bg-katiba-green text-white shadow-sm"
                    : "bg-white text-katiba-gray-800 border border-katiba-gray-200 hover:border-katiba-green hover:text-katiba-green"
                }`}
              >
                {cat}
              </button>
            );
          })}
        </div>

        {/* Master Chapter Grid */}
        {filteredChapters.length === 0 ? (
          <div className="text-center py-16 bg-white rounded-2xl border border-katiba-gray-200 p-8">
            <BookOpen className="w-12 h-12 text-katiba-gray-400 mx-auto mb-3" />
            <h3 className="text-lg font-black text-katiba-black">No chapters match your query</h3>
            <p className="text-sm text-katiba-gray-600 mt-1">
              Try searching with a different constitutional topic or clear the filter.
            </p>
            <button
              onClick={() => {
                setSelectedCategory("All");
                setSearchQuery("");
              }}
              className="mt-4 px-4 py-2 rounded-lg bg-katiba-green text-white text-xs font-bold uppercase tracking-wider hover:bg-katiba-green-dark transition"
            >
              Reset Filters
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredChapters.map((chapter) => (
              <Link
                key={chapter.number}
                href={`/chapters/${chapter.number}`}
                className="group flex flex-col justify-between bg-white rounded-2xl p-6 sm:p-7 border border-katiba-gray-200 shadow-sm hover:border-katiba-green hover:shadow-lg transition-all duration-200"
              >
                <div>
                  {/* Top Bar with Badges */}
                  <div className="flex items-center justify-between gap-2 mb-4">
                    <span className="inline-flex items-center px-3 py-1 rounded-md text-xs font-black tracking-wider uppercase bg-katiba-green text-white">
                      Chapter {chapter.number}
                    </span>
                    <span className="text-xs font-bold text-katiba-gray-600 tracking-wide uppercase">
                      {chapter.articleRange}
                    </span>
                  </div>

                  {/* Chapter Titles */}
                  <h3 className="text-xl font-black text-katiba-black group-hover:text-katiba-green transition-colors leading-snug">
                    {chapter.title}
                  </h3>

                  {chapter.swahiliTitle && (
                    <p className="text-xs font-bold text-katiba-green mt-1">
                      {chapter.swahiliTitle}
                    </p>
                  )}

                  {/* Summary */}
                  <p className="text-sm text-katiba-gray-600 mt-3.5 leading-relaxed font-normal">
                    {chapter.summary}
                  </p>

                  {/* Key Provisions Snippet List */}
                  {chapter.keyProvisions && chapter.keyProvisions.length > 0 && (
                    <div className="mt-5 pt-4 border-t border-katiba-gray-100">
                      <p className="text-[11px] font-black uppercase tracking-wider text-katiba-gray-800 mb-2.5">
                        Key Provisions:
                      </p>
                      <ul className="space-y-2">
                        {chapter.keyProvisions.map((provision, idx) => (
                          <li
                            key={idx}
                            className="flex items-start gap-2 text-xs text-katiba-gray-800 font-medium leading-relaxed"
                          >
                            <span className="w-1.5 h-1.5 rounded-full bg-katiba-red mt-1.5 flex-shrink-0" />
                            <span>{provision}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>

                {/* Footer Link Action */}
                <div className="mt-6 pt-4 border-t border-katiba-gray-100 flex items-center justify-between text-xs font-black text-katiba-black group-hover:text-katiba-green transition-colors">
                  <span className="uppercase tracking-wider">
                    Read Chapter Articles ({chapter.articles.length})
                  </span>
                  <div className="w-7 h-7 rounded-full bg-katiba-gray-100 flex items-center justify-center group-hover:bg-katiba-green group-hover:text-white transition-colors">
                    <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}
